import {PixelWorld,PHYSICS,STEP} from './world.js';
import {CHARACTERS,getCharacter,readCharacterId,saveCharacterId} from './characters.js';
import {measureAtlas} from './sprite-atlas.js';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false});
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
let W=960,H=540,world=new PixelWorld(0),selected=0,mode='menu',loaded=false,time=0,last=0,accumulator=0,camera=0,shake=0,flash=0,toastUntil=0,trailTimer=0,zone=-1;
let particles=[],slashes=[],numbers=[],ghosts=[],keys=new Set,pressed={left:false,right:false,jump:false,attack:false,dash:false,mouseAttack:false,mouseDash:false},assets={},sprites={};
const characterStorage=(()=>{try{return window.localStorage}catch{return null}})();
let characterId=readCharacterId(characterStorage);
const character=()=>getCharacter(characterId);
let soundOn=true,audio,master,nextMusic=0,musicStep=0;
let best={};try{best=JSON.parse(localStorage.getItem('mosslight-pixel-best')||'{}')}catch{}
const rect=(x,y,w,h,color)=>{ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h))};
function text(s,x,y,size=10,color='#edf4cd',align='left'){ctx.font=`${size}px monospace`;ctx.textAlign=align;ctx.fillStyle='#102d31';ctx.fillText(s,Math.round(x)+1,Math.round(y)+2);ctx.fillStyle=color;ctx.fillText(s,Math.round(x),Math.round(y))}
function toast(s,duration=2800){$('toast').textContent=s;$('toast').classList.add('show');toastUntil=performance.now()+duration}
function resize(){const ratio=innerWidth/innerHeight;H=ratio<2/3?Math.round(360/ratio):540;W=ratio<2/3?360:Math.min(1440,Math.round(H*ratio));canvas.width=W;canvas.height=H;ctx.imageSmoothingEnabled=false}addEventListener('resize',resize);resize();
function ensureAudio(){if(!soundOn)return;audio??=new (window.AudioContext||window.webkitAudioContext)();master??=(()=>{const g=audio.createGain();g.gain.value=.2;g.connect(audio.destination);return g})();if(audio.state==='suspended')audio.resume()}
function tone(f,d=.12,kind='triangle',volume=.2,end=f){if(!soundOn||!audio||audio.state!=='running')return;const o=audio.createOscillator(),g=audio.createGain();o.type=kind;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),audio.currentTime+d);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(master);o.start();o.stop(audio.currentTime+d);o.onended=()=>{o.disconnect();g.disconnect()}}
function noise(duration=.07,volume=.35){if(!soundOn||!audio||audio.state!=='running')return;const buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*duration),audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const s=audio.createBufferSource(),g=audio.createGain(),filter=audio.createBiquadFilter();s.buffer=buffer;filter.type='highpass';filter.frequency.value=900;g.gain.value=volume;s.connect(filter);filter.connect(g);g.connect(master);s.start();s.onended=()=>{s.disconnect();filter.disconnect();g.disconnect()}}
function music(){if(!soundOn||!audio||mode!=='playing'||time<nextMusic)return;nextMusic=time+(world.level.night?.27:.46);const melody=world.level.night?[220,329.63,440,293.66,261.63,392,329.63,493.88]:[261.63,329.63,392,523.25,440,392,329.63,293.66];tone(melody[musicStep++%8],.35,'triangle',.07);if(musicStep%4===0)tone(world.level.night?110:130.8,.65,'sine',.12)}
function setSound(){soundOn=!soundOn;$('sound').textContent=soundOn?'♫':'♪';$('sound').setAttribute('aria-label',soundOn?'关闭声音':'开启声音');if(soundOn)ensureAudio()}
function paintPortraits(){document.querySelectorAll('[data-character-portrait]').forEach(cv=>{const id=cv.dataset.characterPortrait==='selected'?characterId:cv.dataset.characterPortrait,sprite=sprites[id],c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);if(!sprite)return;const f=sprite.frames[0],b=f.bounds,w=b.maxX-b.minX+1,h=b.maxY-b.minY+1,scale=Math.min((cv.width-10)/w,(cv.height-8)/h);c.imageSmoothingEnabled=false;c.drawImage(sprite.sheet,f.sx+b.minX,f.sy+b.minY,w,h,Math.round((cv.width-w*scale)/2),Math.round(cv.height-h*scale-4),Math.round(w*scale),Math.round(h*scale))})}
function completionCopy(){return world.level.index?`从晨光到霓虹，${character().name}把光送到了远方。`:`${character().name}已穿过森林，下一段旅程正在霓虹夜城等待。`}
function syncCharacterUI(){const c=character();document.body.dataset.character=c.id;document.documentElement.style.setProperty('--hero-accent',c.accent);document.querySelectorAll('button[data-character]').forEach(b=>{const active=b.dataset.character===c.id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});$('character-intro').textContent=c.intro;$('character-name').textContent=c.name;$('hero-name').textContent=c.name;$('character-english').textContent=c.english;$('character-role').textContent=c.role;$('character-caption').textContent=c.caption;if(mode==='complete')$('modal-copy').textContent=completionCopy();paintPortraits()}
function setCharacter(id){characterId=saveCharacterId(characterStorage,id);syncCharacterUI();return characterId}
function setLevel(n){selected=n;world=new PixelWorld(n);document.body.classList.toggle('night',!!n);document.querySelectorAll('[data-level]').forEach(b=>b.classList.toggle('selected',+b.dataset.level===n));$('start').firstElementChild.textContent=n?'跃入霓虹断层':'出发，去晨露之森';camera=0;particles=[];ghosts=[]}
function begin(n=selected){setLevel(n);mode='playing';accumulator=0;zone=-1;keys.clear();resetTouch();$('menu').classList.add('hidden');$('modal').classList.add('hidden');for(const id of ['hud','pause','touch','play-hint'])$(id).classList.remove('hidden');ensureAudio();toast('空格二段跳 · 左键连斩 · 右键冲刺',4300);updateHud()}
function pause(){if(mode!=='playing')return;mode='paused';keys.clear();resetTouch();$('modal-kicker').textContent='TAKE A BREATH';$('modal-title').textContent='让光停一会儿。';$('modal-copy').textContent='存档灯可以恢复生命。冲刺穿过攻击，光刃弹回敌方弹丸。';$('resume').firstElementChild.textContent='继续旅程';$('results').classList.add('hidden');$('pause-characters').classList.remove('hidden');$('modal').classList.remove('hidden');$('touch').classList.add('hidden')}
function resume(){if(mode==='complete'){if(world.level.index===0)begin(1);else home();return}mode='playing';accumulator=0;keys.clear();resetTouch();$('modal').classList.add('hidden');$('touch').classList.remove('hidden');ensureAudio()}
function home(){mode='menu';keys.clear();resetTouch();toastUntil=0;$('toast').classList.remove('show');for(const id of ['hud','pause','touch','play-hint','boss-hud','modal','combo'])$(id).classList.add('hidden');$('menu').classList.remove('hidden');setLevel(selected)}
function finish(){mode='complete';keys.clear();resetTouch();const s=world.snapshot();best[s.level]=Math.max(best[s.level]||0,s.score);try{localStorage.setItem('mosslight-pixel-best',JSON.stringify(best))}catch{}$('modal-kicker').textContent=world.level.index?'THE LIGHT HAS ARRIVED':'CHAPTER COMPLETE';$('modal-title').textContent=world.level.index?'光，送到了。':'森林在身后闪耀。';$('modal-copy').textContent=completionCopy();$('results').innerHTML=`<div><b>${s.score}</b><span>旅程积分</span></div><div><b>${s.kills}</b><span>击败敌人</span></div><div><b>${s.bestCombo}</b><span>最高连击</span></div>`;$('results').classList.remove('hidden');$('pause-characters').classList.add('hidden');$('resume').firstElementChild.textContent=world.level.index?'返回选关':'进入霓虹断层';$('modal').classList.remove('hidden');$('touch').classList.add('hidden');tone(659,.4,'triangle',.25);setTimeout(()=>tone(988,.8,'sine',.2),180)}
function resetTouch(){Object.keys(pressed).forEach(k=>pressed[k]=false);document.querySelectorAll('[data-key]').forEach(b=>b.classList.remove('held'))}
$('start').onclick=()=>begin();$('pause').onclick=pause;$('resume').onclick=resume;$('home').onclick=home;$('restart').onclick=()=>begin(selected);$('sound').onclick=setSound;
$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});else document.documentElement.requestFullscreen?.().catch(()=>toast('当前窗口暂不支持全屏'))};
document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>setLevel(+b.dataset.level));
document.querySelectorAll('button[data-character]').forEach(b=>b.onclick=()=>setCharacter(b.dataset.character));
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyJ','KeyK'].includes(e.code))e.preventDefault();if(e.code==='Escape'){mode==='playing'?pause():mode==='paused'?resume():null;return}if(e.code==='KeyM'&&!e.repeat)setSound();if(e.code==='KeyF'&&!e.repeat)$('fullscreen').click();if(e.code==='KeyR'&&!e.repeat&&mode==='playing')world.respawn();keys.add(e.code)});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',pause);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});
canvas.addEventListener('mousedown',e=>{if(mode!=='playing'||![0,2].includes(e.button))return;e.preventDefault();pressed[e.button===0?'mouseAttack':'mouseDash']=true});addEventListener('mouseup',e=>{if(e.button===0)pressed.mouseAttack=false;if(e.button===2)pressed.mouseDash=false});canvas.addEventListener('pointercancel',()=>{pressed.mouseAttack=false;pressed.mouseDash=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);pressed[b.dataset.key]=true;b.classList.add('held')});const up=()=>{pressed[b.dataset.key]=false;b.classList.remove('held')};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
function input(){return {x:(keys.has('KeyD')||keys.has('ArrowRight')||pressed.right?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')||pressed.left?1:0),jump:keys.has('Space')||keys.has('KeyW')||keys.has('ArrowUp')||pressed.jump,attack:keys.has('KeyJ')||pressed.attack||pressed.mouseAttack,dash:keys.has('KeyK')||keys.has('ShiftLeft')||keys.has('ShiftRight')||pressed.dash||pressed.mouseDash}}
function burst(x,y,n,colors,power=150){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=power*(.25+Math.random());particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-35,life:.2+Math.random()*.4,max:.6,size:2+Math.random()*4,color:colors[i%colors.length],gravity:400})}if(particles.length>420)particles.splice(0,particles.length-420)}
function processEvents(){for(const e of world.drain()){
 if(e.type==='swing'){slashes.push({...e,characterId,life:.18,max:.18});noise(.065,.18);tone(e.stage===2?200:370,.07,'sawtooth',.08,70)}
 if(e.type==='hit'){shake=Math.max(shake,e.heavy?7:3.6);flash=Math.max(flash,e.kill?.07:.025);burst(e.x,e.y,e.kill?28:15,character().impact,e.heavy?330:210);numbers.push({x:e.x,y:e.y-22,s:e.heavy?'CRITICAL':`−${e.damage}`,life:.6,color:e.heavy?character().heavy:'#fff8df'});noise(.085,.55);tone(e.heavy?90:150,.12,'square',.3,35)}
 if(e.type==='kill'){burst(e.x,e.y,e.boss?80:22,world.level.night?['#f3a3df','#88f7eb','#dce7fa']:['#bde595','#ffdca4','#f39e7e'],e.boss?380:160);if(e.boss){shake=13;flash=.2}}
 if(e.type==='hurt'){shake=8;flash=.12;burst(e.x,e.y,16,['#f3877c','#f9b3a0'],160);tone(180,.2,'sawtooth',.3,40)}
 if(e.type==='jump'){burst(e.x,e.y,e.air?12:7,['#c3f7d4','#f0e5b2'],75);tone(e.air?520:320,.14,'triangle',.16,830)}
 if(e.type==='dash'){burst(e.x+11,e.y+22,15,character().impact,170);tone(590,.13,'sawtooth',.08,120);noise(.12,.12)}
 if(e.type==='coin'){burst(e.x,e.y,6,e.rare?['#ffbff1','#b8ffec']:['#fff0ad','#e9cb73'],85);tone(e.rare?1318:987,.16,'sine',.13)}
 if(e.type==='checkpoint'){toast(`存档灯 ${e.id} 已点亮 · 生命恢复`);burst(e.x,e.y-35,30,['#beffc9','#ffefae'],150);tone(660,.4,'sine',.2)}
 if(e.type==='respawn'){camera=clamp(world.player.x-W*.3,0,world.level.length-W);toast('从存档灯重新出发，收藏与击败记录保留。');shake=3}
 if(e.type==='bossDefeated')toast('守卫已击败 · 前往右侧光门',4800);
 if(e.type==='parry'){toast('弹反！',900);burst(e.x,e.y,25,['#eefff8','#8dffee'],250);tone(1500,.18,'triangle',.25);shake=4}
 if(e.type==='slam'){shake=10;burst(e.x,e.y,30,['#f9c6ae','#baffd4'],240);tone(65,.35,'sawtooth',.35,25)}
 if(e.type==='heal'){toast('战斗补给 · 恢复 1 格生命',1800);tone(880,.35,'sine',.18)}
 if(e.type==='complete')finish();
 }}
function updateHud(){const p=world.player,l=world.level;$('hearts').innerHTML=Array.from({length:p.maxHp},(_,i)=>`<i class="${i<p.hp?'':'empty'}"></i>`).join('');$('dash-ready').style.width=`${(1-p.dashCooldown/.7)*100}%`;$('dash-label').textContent=p.dashCooldown>0?'冲刺充能':'冲刺就绪';$('score').textContent=String(world.score).padStart(6,'0');$('coins').textContent=`✧ ${world.collected.size}`;$('chapter-name').textContent=`0${l.index+1} / ${l.name}`;$('checkpoint').textContent=`存档 ${world.checkpoint+1} / ${l.checkpoints.length}`;$('progress').style.width=`${p.x/l.length*100}%`;const z=Math.min(3,Math.floor(p.x/l.length*4));$('zone').textContent=l.zones[z];if(zone!==z){zone=z;if(z>0)toast(l.zones[z],2200)}$('combo').classList.toggle('hidden',world.combo<2);$('combo').querySelector('b').textContent=world.combo;const boss=world.enemies.find(e=>e.type==='boss'),show=!boss.dead&&p.x>boss.home.x-250;$('boss-hud').classList.toggle('hidden',!show||mode==='menu');$('boss-name').textContent=l.boss;$('boss-hp').style.width=`${boss.hp/boss.maxHp*100}%`}
function backdrops(){const night=world.level.night,img=night?assets.city:assets.forest;rect(0,0,W,H,night?'#182744':'#7eb5a0');if(img){const scale=Math.max(W/img.width,H/img.height)*1.12,w=img.width*scale,h=img.height*scale;const drift=Math.sin(camera*.00021)*W*.035;ctx.drawImage(img,Math.round((W-w)/2-drift),Math.round((H-h)/2-12),Math.ceil(w),Math.ceil(h));}rect(0,0,W,H,night?'#0b183230':'#143c2724');
 // Mid-distance silhouettes scroll more quickly than the scenic painting.
 const step=night?180:230;for(let i=Math.floor(camera*.25/step)-1;i<(camera*.25+W)/step+2;i++){const x=i*step-camera*.25,seed=Math.abs(Math.sin(i*73.1)),height=70+seed*160;if(night){rect(x,H-height,70+seed*45,height,'#14233acc');rect(x-3,H-height,78+seed*45,3,'#5697ba88');for(let y=H-height+12;y<H-30;y+=18)for(let xx=x+10;xx<x+62;xx+=15)if(Math.sin(xx+y)>.1)rect(xx,y,5,8,'#78ced342')}else{rect(x+12,H-height,12,height,'#31534765');for(let j=0;j<3;j++){ctx.fillStyle='#39655166';ctx.beginPath();ctx.moveTo(x+18,H-height-28+j*22);ctx.lineTo(x-35-j*8,H-height+80+j*22);ctx.lineTo(x+71+j*8,H-height+80+j*22);ctx.fill()}}}
 for(let i=0;i<40;i++){const x=(i*139.3+time*(night?-38:7)-camera*.08)%(W+60),y=(i*73.7+time*(night?180:-5))%(H+40);rect(x,y,night?1:2,night?14:2,night?'#8ebad84d':'#fff3a980')}
}
function terrain(a){if(a.gone){rect(a.x-camera,a.y,a.w,2,'#ea8e9c80');return}const x=a.x-camera,y=a.y,night=world.level.night;if(x+a.w< -30||x>W+30)return;
 const crumb=a.kind==='crumble'&&a.trigger>=0;const color=crumb?'#7f687e':night?'#253149':'#33483c';rect(x,y,a.w,a.h,color);rect(x,y,a.w,5,night?'#7dc9ce':'#9dca79');rect(x,y+5,a.w,4,night?'#385b72':'#668c50');rect(x,y+a.h-4,a.w,4,'#102e36');
 for(let xx=Math.floor(x/20)*20;xx<x+a.w;xx+=20){const left=Math.max(xx,x),width=Math.min(17,x+a.w-left);if(width<=0)continue;rect(left,y+12,width,4,night?'#35445d':'#50664a');if(a.kind==='ground'){for(let yy=y+26;yy<H;yy+=24){rect(left+4,yy,Math.max(1,width-5),2,night?'#1b293f':'#283c32');if(night&&Math.sin(xx+yy)>.4)rect(left+6,yy+7,4,6,'#75c7ce55')}}}
 if(night){for(let xx=x+9;xx<x+a.w;xx+=48)rect(xx,y+1,18,2,crumb?'#ffa2d7':'#bbf4e5');if(a.kind==='ground'){rect(x+9,y+27,18,36,'#101f31');rect(x+a.w-23,y+33,5,24,'#7be4d370');rect(x+3,y+14,3,90,'#8f79a14d')}}else{for(let xx=x+6;xx<x+a.w-4;xx+=15){const n=Math.abs(Math.sin(xx*.073+a.id));rect(xx,y-4-n*5,3,7+n*5,'#89b961');if(n>.58){rect(xx+2,y-6,4,3,'#f0d694');rect(xx+3,y-9,2,3,'#ffedd0')}}if(a.kind==='ledge'){for(let xx=x+9;xx<x+a.w;xx+=27){rect(xx,y+a.h,2,18,'#668f53');rect(xx-3,y+a.h+10,5,3,'#7fa261')}}}
 if(a.kind==='moving'){rect(x+12,y+a.h+5,a.w-24,2,'#8ef7e1');for(let xx=x+20;xx<x+a.w;xx+=25)rect(xx,y+a.h+8,3,5,'#abf2df')}
 if(crumb){rect(x+25,y+1,3,a.h,'#d9afb5');rect(x+53,y+3,2,a.h-2,'#d9afb5')}
}
function decoration(){const l=world.level;for(const c of l.checkpoints){const x=c.x-camera;if(x< -100||x>W+100)continue;rect(x-7,c.y-47,14,47,'#28463d');rect(x-12,c.y-50,24,5,'#a8c599');rect(x-9,c.y-45,18,21,c.id<=world.checkpoint?'#e7f4b3':'#588773');rect(x-4,c.y-40,8,13,c.id<=world.checkpoint?'#fff4b2':'#93b7a0');rect(x-15,c.y-4,30,5,'#687e57');if(c.id<=world.checkpoint){ctx.fillStyle='#efffb31a';ctx.fillRect(Math.round(x-23),Math.round(c.y-62),46,58)}}
 for(const d of l.decor){const x=d.x-camera;if(x< -80||x>W+100)continue;if(d.kind==='sign'&&d.text){rect(x,d.y-30,3,30,'#635d43');rect(x-22,d.y-44,57,18,l.night?'#25485d':'#9e996c');text(d.text,x+5,d.y-32,8,l.night?'#b6f7e8':'#203d33','center')}
 if(d.kind==='chest'){rect(x,d.y-17,24,17,'#735741');rect(x-2,d.y-20,28,8,'#d0ad67');rect(x+10,d.y-11,5,7,'#f7d884')}
 if(d.kind==='gate'){const boss=world.enemies.find(e=>e.type==='boss'),open=boss.dead;rect(x-27,d.y-84,7,84,'#799789');rect(x+20,d.y-84,7,84,'#799789');rect(x-27,d.y-90,54,9,'#c7dcb6');rect(x-20,d.y-80,40,78,open?'#c6f8d080':'#20343a80');if(open){for(let j=0;j<6;j++)rect(x-17+j*6,d.y-77,2,74,`rgba(223,255,192,${.2+Math.sin(time*4+j)*.15})`)}text(open?'前往光门':'击败守卫',x,d.y-107,9,open?'#f0ffba':'#efc6b0','center')}}
 for(const h of world.hazards){const x=h.x-camera;if(x<-100||x>W+100)continue;rect(x,h.y,h.w,10,'#2d374d');for(let i=0;i<h.w;i+=9)rect(x+i,h.y,5,3,h.warning?'#f2c276':h.active?'#ff869c':'#79b1b2');if(h.active){rect(x,h.y-19,h.w,2,'#ff93a3');rect(x,h.y-17,h.w,17,'#f2658c30')}}
}
function diamond(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(Math.round(x),Math.round(y-r));ctx.lineTo(Math.round(x+r*.6),Math.round(y));ctx.lineTo(Math.round(x),Math.round(y+r));ctx.lineTo(Math.round(x-r*.6),Math.round(y));ctx.fill()}
function pickups(){world.level.coins.forEach((c,i)=>{if(world.collected.has(i))return;const x=c.x-camera;if(x< -20||x>W+20)return;const y=c.y+Math.sin(time*3+i)*3;diamond(x,y,c.rare?11:7,c.rare?'#e8a2e0':'#f7d98f');rect(x-1,y-3,2,5,'#fff8c5')})}
function enemy(e){if(e.dead)return;const x=Math.round(e.x-camera),y=Math.round(e.y),t=world.time;if(x<-100||x>W+100)return;ctx.save();const hit=e.flash>0,night=world.level.night,warning=e.mode==='windup';const light=hit?'#fffbdc':warning?'#f8c386':night?'#c685b1':'#b4cc86',dark=hit?'#fffbdc':night?'#303447':'#506647',eye=hit?'#fff':'#ffe0a0';
 if(e.type==='slime'){const bob=Math.sin(t*6+e.id)*2;rect(x+3,y+8+bob,22,21-bob,dark);rect(x+6,y+3+bob,16,26-bob,light);rect(x,y+20,28,10,dark);rect(x+5,y+11+bob,18,15,light);rect(x+7,y+13,4,4,'#1b3739');rect(x+18,y+13,4,4,'#1b3739');rect(x+10,y-1+bob,3,8,'#8fb977');rect(x+13,y-3+bob,6,4,'#d6e8a3')}
 else if(e.type==='wisp'||e.type==='drone'){const flap=Math.sin(t*14)*4;rect(x+4,y+3,20,17,dark);rect(x+8,y,12,23,light);rect(x-9,y+5+flap,15,5,night?'#77dfe0':'#baddce');rect(x+23,y+5-flap,15,5,night?'#77dfe0':'#baddce');rect(x+7,y+8,14,5,eye);rect(x+11,y+9,6,3,'#304d50');rect(x+10,y+24,8,3,'#7adedaa0')}
 else if(e.type==='boss'){const bounce=Math.sin(t*3)*2;rect(x+10,y+e.h-20,17,20,dark);rect(x+38,y+e.h-20,17,20,dark);rect(x+7,y+25+bounce,50,e.h-39,dark);rect(x+13,y+20+bounce,38,e.h-34,light);rect(x+15,y+2+bounce,34,25,dark);rect(x+19,y+5+bounce,26,21,light);rect(x+20,y+13+bounce,24,5,night?'#85ffee':'#fff3bd');rect(x-8,y+27+bounce,18,34,dark);rect(x+53,y+27+bounce,18,34,dark);rect(x-11,y+29+bounce,20,17,light);rect(x+55,y+29+bounce,20,17,light);diamond(x+32,y+42+bounce,11,night?'#86efff':'#f5db8d');if(night){rect(x+10,y-9,5,23,'#a77ad4');rect(x+49,y-9,5,23,'#a77ad4');rect(x+23,y+e.h-5,5,5,'#80fbea')}else{rect(x+8,y-4,10,18,'#708c58');rect(x+45,y-3,12,15,'#708c58');rect(x+2,y-8,18,7,'#abc888');rect(x+45,y-6,18,7,'#abc888')}
 }else{const brute=e.type==='brute',w=e.w;rect(x+5,y+e.h-12,8,12,dark);rect(x+w-13,y+e.h-12,8,12,dark);rect(x+3,y+11,w-6,e.h-17,dark);rect(x+7,y+14,w-14,14,light);rect(x+5,y,w-10,15,light);rect(x+8,y+6,w-16,4,eye);rect(x-4,y+16,9,15,light);rect(x+w-5,y+16,9,15,light);if(brute){rect(x-8,y+26,14,12,dark);rect(x+w-5,y+26,14,12,dark);rect(x+10,y-5,w-20,6,night?'#edabda':'#819c62')}if(e.type==='sentry'){rect(x+(e.dir>0?w-3:-17),y+15,20,6,'#86d5d9');rect(x+9,y-12,3,14,'#bb86a5')}}
 if(e.hp<e.maxHp&&e.type!=='boss'){rect(x-1,y-10,e.w+2,3,'#163134');rect(x,y-9,e.w*e.hp/e.maxHp,1,'#f0c495')}
 if(warning){text('!',x+e.w/2,y-19,18,'#ffe1a1','center');if(e.type==='boss')rect(x+(e.dir<0?-130:0),e.home.y-2,190,2,'#fac6a590')}
 ctx.restore();}
function drawHero(frame,x,y,face=1,multiplier=1,alpha=1,id=characterId,tinted=false){const sprite=sprites[id],f=sprite?.frames[frame];if(!f)return;const scale=sprite.scale*multiplier;ctx.save();ctx.globalAlpha=alpha;ctx.translate(Math.round(x),Math.round(y));ctx.scale(face,1);ctx.drawImage(tinted?sprite.tint: sprite.sheet,f.sx,f.sy,f.sw,f.sh,Math.round(-f.ax*scale),Math.round(-f.ay*scale),Math.ceil(f.sw*scale),Math.ceil(f.sh*scale));ctx.restore()}
function hero(){const p=world.player;let frame=0;if(p.hurt>0)frame=7;else if(p.dash>0)frame=6;else if(p.attack>0)frame=p.attackStage===1?5:4;else if(!p.grounded)frame=3;else if(Math.abs(p.vx)>25)frame=1+Math.floor(world.time*10)%2;
 if(p.dash>0&&world.time-trailTimer>.025){ghosts.push({x:p.x+p.w/2,y:p.y+p.h,face:p.face,frame:6,characterId,life:.2});trailTimer=world.time}
 for(const g of ghosts)drawHero(g.frame,g.x-camera,g.y,g.face,1,g.life*1.7,g.characterId,true);
 const blink=p.invuln>0&&p.dash<=0?Math.floor(time*18)%2?.45:1:1;drawHero(frame,p.x+p.w/2-camera,p.y+p.h+1,p.face,1,blink);
}
function fx(dt){for(const s of slashes){const a=1-s.life/s.max,x=s.x-camera+s.face*35,y=s.y,rx=s.stage===2?73:57,ry=s.stage===1?54:30,palette=getCharacter(s.characterId);ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(s.face,1);ctx.globalAlpha=Math.min(1,s.life*10);ctx.lineWidth=s.stage===2?8:5;ctx.strokeStyle=s.stage===2?palette.heavy:palette.slash;ctx.beginPath();ctx.ellipse(0,0,rx,ry,-.2,-1.2+a*.3,1.15+a*.3);ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#fffde2';ctx.beginPath();ctx.ellipse(0,-3,rx+7,ry+3,-.2,-1.3+a*.2,1.0+a*.2);ctx.stroke();ctx.restore();s.life-=dt}
 slashes=slashes.filter(s=>s.life>0);for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.gravity*dt;ctx.globalAlpha=Math.min(1,p.life*5);rect(p.x-camera,p.y,p.size,p.size,p.color)}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);for(const n of numbers){n.life-=dt;n.y-=dt*32;ctx.globalAlpha=Math.min(1,n.life*5);text(n.s,n.x-camera,n.y,n.s==='CRITICAL'?11:13,n.color,'center')}ctx.globalAlpha=1;numbers=numbers.filter(n=>n.life>0);ghosts.forEach(g=>g.life-=dt);ghosts=ghosts.filter(g=>g.life>0)}
function render(dt){backdrops();if(mode==='menu'){const portrait=H>W,floorY=H*(portrait?.365:.83),x=W*(portrait?.68:.73),previewScale=portrait?2.25:4.1;rect(x-110,floorY,265,12,world.level.night?'#406373':'#9aa973');rect(x-110,floorY+12,265,90,world.level.night?'#1b2b42':'#334b3d');rect(x-100,floorY+4,245,3,'#cfedb380');drawHero(0,x+10,floorY+2,1,previewScale);for(let i=0;i<14;i++){const px=x-90+i*19,py=floorY-10+Math.sin(time*2+i)*5;rect(px,py,2,2,character().accent)}return}
 const motion=mode==='playing'?dt:0;shake=Math.max(0,shake-motion*35);flash=Math.max(0,flash-motion);ctx.save();ctx.translate(Math.round((Math.random()-.5)*shake),Math.round((Math.random()-.5)*shake)+Math.max(0,H*.76-420));for(const a of world.platforms)terrain(a);decoration();pickups();for(const e of world.enemies)enemy(e);for(const b of world.projectiles){diamond(b.x-camera+6,b.y+6,8,b.owner==='player'?'#b9ffec':'#f7a4bc');rect(b.x-camera-b.vx*.025,b.y+4,Math.abs(b.vx)*.023,3,b.owner==='player'?'#b9ffec77':'#f7a4bc66')}hero();fx(motion);ctx.restore();if(flash>0)rect(0,0,W,H,`rgba(255,234,197,${Math.min(.16,flash)})`);
}
let hudTime=0;
function frame(ms){requestAnimationFrame(frame);const dt=Math.min((ms-last)/1000||.016,.045);last=ms;if(mode==='playing'||mode==='menu')time+=dt;if(mode==='playing'){accumulator+=dt;while(accumulator>=STEP&&mode==='playing'){world.step(STEP,input());processEvents();accumulator-=STEP}const target=clamp(world.player.x-W*.36+world.player.vx*.16,0,Math.max(0,world.level.length-W));camera+=(target-camera)*(1-Math.exp(-dt*7));hudTime+=dt;if(hudTime>.08){updateHud();hudTime=0}music()}if(ms>toastUntil)$('toast').classList.remove('show');render(dt)}
function image(src){return new Promise((resolve,reject)=>{const i=new Image;i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('无法读取素材 '+src));i.src=src})}
function prepareCharacter(sheet,metadata){const cv=document.createElement('canvas');cv.width=sheet.width;cv.height=sheet.height;const c=cv.getContext('2d',{willReadFrequently:true});c.drawImage(sheet,0,0);const frames=measureAtlas(c.getImageData(0,0,cv.width,cv.height).data,cv.width,cv.height,{edgeInset:Math.round(sheet.width/128)}),idle=frames[0].bounds;c.globalCompositeOperation='source-in';c.fillStyle=metadata.trail;c.fillRect(0,0,cv.width,cv.height);return {sheet,frames,tint:cv,scale:metadata.drawHeight/(idle.maxY-idle.minY+1)}}
async function init(){setCharacter(characterId);try{const [forest,city,...sheets]=await Promise.all([image('assets/forest.png'),image('assets/city.png'),...CHARACTERS.map(c=>image(c.asset))]);assets={forest,city};CHARACTERS.forEach((c,i)=>sprites[c.id]=prepareCharacter(sheets[i],c));loaded=true;paintPortraits();$('start').disabled=false;setLevel(0)}catch(e){$('start').firstElementChild.textContent='素材加载失败，点击刷新';$('start').disabled=false;$('start').onclick=()=>location.reload();console.error(e)}requestAnimationFrame(frame)}
window.pixelInfo=()=>({...world.snapshot(),mode,loaded,sound:soundOn,characterId,characterName:character().name,frames:sprites[characterId]?.frames.length||0,characterFrames:Object.fromEntries(CHARACTERS.map(c=>[c.id,sprites[c.id]?.frames.length||0])),camera,particles:particles.length,slashes:slashes.length});
if(new URLSearchParams(location.search).has('qa'))window.__pixelQA={world:()=>world,begin,pause,resume,home,setCharacter};
init();
